/* ==========================================================================
   Checkbox — "select all" and its mixed state. Spec: elements/checkbox.md

   A checkbox whose aria-controls lists other checkboxes' ids controls them:
   checking it checks them all, clearing it clears them, and while only some
   are checked it shows mixed. `indeterminate` exists only in script, so the
   select-all box ships inside a `hidden` .checkbox and this reveals it.
   ========================================================================== */
(function () {
  "use strict";
  document.querySelectorAll('input[type="checkbox"][aria-controls]:not([role="switch"])').forEach(function (all) {
    var kids = all
      .getAttribute("aria-controls")
      .split(/\s+/)
      .map(function (id) {
        return document.getElementById(id);
      })
      .filter(function (k) {
        return k && k.type === "checkbox";
      });
    if (!kids.length) return;
    // it ships hidden: without this script it would be a box that does nothing
    var wrap = all.closest(".checkbox");
    if (wrap) wrap.hidden = false;
    function sync() {
      var n = kids.filter(function (k) {
        return k.checked;
      }).length;
      all.checked = n === kids.length;
      all.indeterminate = n > 0 && n < kids.length;
    }
    all.addEventListener("change", function () {
      kids.forEach(function (k) {
        k.checked = all.checked;
      });
    });
    kids.forEach(function (k) {
      k.addEventListener("change", sync);
    });
    sync();
  });
})();

/* ==========================================================================
   Field — the search field's clear button. Spec: elements/field.md

   It shows only while the field has text. Pressed, it puts focus back in
   the input, empties it and fires `input`, so a filtered list updates and
   the button hides without dropping focus on the page.
   ========================================================================== */
(function () {
  "use strict";
  document.querySelectorAll(".field__box").forEach(function (box) {
    var input = box.querySelector(".field__input");
    var clear = box.querySelector(".field__clear");
    if (!input || !clear) return;
    function sync() {
      clear.hidden = input.value === "";
    }
    input.addEventListener("input", sync);
    clear.addEventListener("click", function () {
      input.focus();
      input.value = "";
      input.dispatchEvent(new Event("input", { bubbles: true }));
    });
    sync();
  });
})();

/* ==========================================================================
   Form — errors on submit. Spec: elements/form.md

   Without this file the browser's own validation runs. With it, the browser
   still decides what is wrong (required, pattern, type), but instead of its
   bubble each field shows Field's error, and the summary at the top lists
   them as links and takes focus. A field shown wrong is checked again on
   blur, or on change for a choice: never while typing.
   ========================================================================== */
(function () {
  "use strict";
  // a control's box is its .field, or a group's fieldset: it holds one .field__error
  function box(el) { return el.closest ? el.closest("fieldset, .field") : null; }
  function errorOf(el) { var b = box(el); return b && b.querySelector(".field__error"); }
  function mark(el) { // show or clear one control's error; returns it if shown
    var err = errorOf(el), bad = !el.validity.valid;
    if (!err) return null;
    var owner = box(el).localName === "fieldset" ? box(el) : el; // a group is described as one
    var ids = (owner.getAttribute("aria-describedby") || "").split(/\s+/)
      .filter(function (id) { return id && id !== err.id; });
    if (bad) ids.unshift(err.id); // the fix first, then the help
    if (ids.length) owner.setAttribute("aria-describedby", ids.join(" "));
    else owner.removeAttribute("aria-describedby");
    if (owner === el && bad) el.setAttribute("aria-invalid", "true");
    else if (owner === el) el.removeAttribute("aria-invalid");
    err.hidden = !bad;
    return bad ? err : null;
  }
  document.querySelectorAll("form.form").forEach(function (form) {
    var summary = form.querySelector(".form__summary"), queued = 0;
    form.addEventListener("invalid", function (e) { // no bubble: ours, once all are checked
      if (!errorOf(e.target)) return; // a control with no error slot keeps the browser's own
      e.preventDefault();
      if (!queued) queued = setTimeout(report);
    }, true);
    function report() {
      var wrong = [], seen = {};
      queued = 0;
      Array.prototype.forEach.call(form.elements, function (el) {
        if (!el.willValidate || (el.type === "radio" && seen[el.name])) return;
        seen[el.name] = true;
        var err = mark(el);
        if (err) wrong.push({ el: el, text: err.textContent.trim() });
      });
      if (!wrong.length) return;
      if (!summary) return wrong[0].el.focus(); // one field: its error is in view
      var list = summary.querySelector("ul");
      list.textContent = "";
      wrong.forEach(function (w) {
        var li = list.appendChild(document.createElement("li"));
        var a = li.appendChild(document.createElement("a"));
        a.href = "#" + w.el.id;
        a.textContent = w.text;
      });
      summary.querySelector(".card__title").textContent =
        wrong.length === 1 ? "Fix 1 thing" : "Fix " + wrong.length + " things";
      summary.hidden = false;
      summary.focus();
    }
    function recheck(e) {
      var err = errorOf(e.target);
      if (err && !err.hidden && e.target.willValidate) mark(e.target);
    }
    form.addEventListener("focusout", recheck);
    form.addEventListener("change", recheck);
    if (summary) summary.addEventListener("click", function (e) { // caret in, label in view
      var a = e.target.closest("a[href^='#']");
      var el = a && document.getElementById(a.getAttribute("href").slice(1));
      if (!el) return;
      e.preventDefault();
      (box(el).querySelector("legend, label") || el).scrollIntoView({ block: "start" });
      el.focus({ preventScroll: true });
    });
  });
})();

/* ==========================================================================
   frame.js — publishes --chrome on every .frame. Spec: elements/frame.md
   --------------------------------------------------------------------------
   --chrome is the part of the frame's height that isn't room for content:
   the bars with their safe areas, and the scroll region's own padding. So
   100svh - var(--chrome) is the room, and the study card fits in it.

   CSS can't put a content-sized bar's height into a property, so this
   measures it, in px, whenever the frame or anything in it changes size
   (text size, a bar wrapping, a rotation). Without script --chrome stays
   unset: the study card falls back to 100svh and the region scrolls a
   little. Nothing else reads it.
   ========================================================================== */
(function () {
  "use strict";
  if (!("ResizeObserver" in window)) return;

  function measure(frame) {
    var scroll = frame.querySelector(":scope > .frame__scroll");
    if (!scroll) return;
    var cs = getComputedStyle(scroll);
    var room = scroll.clientHeight - parseFloat(cs.paddingTop) - parseFloat(cs.paddingBottom);
    var chrome = frame.getBoundingClientRect().height - room;
    frame.style.setProperty("--chrome", Math.max(0, Math.round(chrome)) + "px");
  }

  var ro = new ResizeObserver(function (entries) {
    var done = [];
    entries.forEach(function (e) {
      var frame = e.target.classList.contains("frame") ? e.target : e.target.parentElement;
      if (frame && done.indexOf(frame) < 0) {
        done.push(frame);
        measure(frame);
      }
    });
  });

  Array.prototype.forEach.call(document.querySelectorAll(".frame"), function (frame) {
    ro.observe(frame);
    Array.prototype.forEach.call(frame.children, function (child) {
      ro.observe(child);
    });
  });
})();

/* ==========================================================================
   Stepper — the − and + buttons. Spec: elements/stepper.md

   The buttons ship hidden, so without this the value is a number field you
   type in. This shows them and steps the value within data-min, data-max
   and data-step, firing input and change. At a limit the button turns
   aria-disabled and stays focusable; a press there reads out why (its
   description, the help) instead of doing nothing. Up and Down step from
   inside the value. A status line reads each new value out.
   ========================================================================== */
(function () {
  "use strict";
  document.querySelectorAll(".stepper").forEach(function (box) {
    var input = box.querySelector(".stepper__input");
    var down = box.querySelector(".stepper__down");
    var up = box.querySelector(".stepper__up");
    if (!input || !down || !up) return;
    var min = Number(input.dataset.min || 0);
    var max = Number(input.dataset.max || Infinity);
    var step = Number(input.dataset.step || 1);
    var status = document.createElement("span");
    status.className = "sr-only";
    status.setAttribute("role", "status");
    box.appendChild(status);

    function current() {
      var v = parseInt(input.value, 10);
      return isNaN(v) ? null : v;
    }
    function sync() {
      var v = current();
      down.setAttribute("aria-disabled", String(v !== null && v <= min));
      up.setAttribute("aria-disabled", String(v !== null && v >= max));
    }
    function say(text) {
      // the same words twice running are still read out: vary them unseen
      status.textContent = status.textContent === text ? text + " " : text;
    }
    function move(dir, button) {
      if (button && button.getAttribute("aria-disabled") === "true") {
        var ids = (button.getAttribute("aria-describedby") || "").split(/\s+/);
        say(ids.map(function (id) {
          var el = id && document.getElementById(id);
          return el ? el.textContent.trim() : "";
        }).join(" ").trim());
        return;
      }
      var v = current();
      // a typed value between steps goes to the next step in that direction
      var n = v === null ? min
        : dir > 0 ? min + (Math.floor((v - min) / step) + 1) * step
        : min + (Math.ceil((v - min) / step) - 1) * step;
      n = Math.min(max, Math.max(min, n));
      if (n === v) return;
      input.value = String(n);
      input.dispatchEvent(new Event("input", { bubbles: true }));
      input.dispatchEvent(new Event("change", { bubbles: true }));
      say(input.value);
    }

    down.addEventListener("click", function () { move(-1, down); });
    up.addEventListener("click", function () { move(1, up); });
    input.addEventListener("keydown", function (e) {
      if (e.key !== "ArrowUp" && e.key !== "ArrowDown") return;
      e.preventDefault();
      move(e.key === "ArrowUp" ? 1 : -1);
    });
    input.addEventListener("input", sync);
    down.hidden = false;
    up.hidden = false;
    sync();
  });
})();

/* ==========================================================================
   Tabs — sections of one screen. Spec: elements/tabs.md

   The markup is links to stacked sections, which is what you get without
   this. This makes ARIA tabs of it: the list becomes a tablist, each link a
   tab that controls its section, each section a tabpanel labelled by its
   tab. One tab stop (a roving tabindex); Left and Right move and select
   (automatic activation), wrapping at the ends and following the writing
   direction; Home and End go to the first and last. A click or a tap
   selects without jumping the page. A #hash naming a panel selects it.
   A .tabs carrying data-sg-static is left alone: the style sheet uses it to
   show the form without script.
   ========================================================================== */
(function () {
  "use strict";
  document.querySelectorAll(".tabs").forEach(function (box) {
    if (box.hasAttribute("data-sg-static")) return;
    var list = box.querySelector(".tabs__list");
    if (!list) return;
    var tabs = Array.prototype.slice.call(list.querySelectorAll(".tabs__tab"));
    var panels = tabs.map(function (tab) {
      var id = (tab.getAttribute("href") || "").replace(/^#/, "");
      return id ? document.getElementById(id) : null;
    });
    if (!tabs.length || panels.indexOf(null) !== -1) return;

    list.setAttribute("role", "tablist");
    tabs.forEach(function (tab, i) {
      var panel = panels[i];
      if (!tab.id) tab.id = panel.id + "-tab";
      tab.setAttribute("role", "tab");
      tab.setAttribute("aria-controls", panel.id);
      panel.setAttribute("role", "tabpanel");
      panel.setAttribute("aria-labelledby", tab.id);
      panel.tabIndex = 0;
    });

    var current = -1;
    function select(i, focus) {
      tabs.forEach(function (tab, n) {
        var on = n === i;
        tab.setAttribute("aria-selected", String(on));
        tab.tabIndex = on ? 0 : -1;
        panels[n].hidden = !on;
      });
      current = i;
      if (focus) tabs[i].focus();
    }

    function fromHash() {
      var id = location.hash.slice(1);
      for (var n = 0; n < panels.length; n++) if (id && panels[n].id === id) return n;
      return -1;
    }

    list.addEventListener("click", function (e) {
      var tab = e.target.closest(".tabs__tab");
      if (!tab || tabs.indexOf(tab) === -1) return;
      e.preventDefault();
      select(tabs.indexOf(tab), true);
    });

    list.addEventListener("keydown", function (e) {
      var i = tabs.indexOf(document.activeElement);
      if (i === -1) return;
      var rtl = getComputedStyle(list).direction === "rtl";
      var next = { ArrowRight: rtl ? -1 : 1, ArrowLeft: rtl ? 1 : -1 }[e.key];
      var to = -1;
      if (next) to = (i + next + tabs.length) % tabs.length;
      else if (e.key === "Home") to = 0;
      else if (e.key === "End") to = tabs.length - 1;
      else if (e.key === " ") to = i; // a link ignores Space; a tab takes it
      else return;
      e.preventDefault();
      select(to, true);
    });

    window.addEventListener("hashchange", function () {
      var n = fromHash();
      if (n !== -1 && n !== current) select(n, false);
    });

    var start = fromHash();
    select(start === -1 ? 0 : start, false);
  });
})();
